// Format the response
const claudeResponse = $input.item.json;
const metadata = $('Process Operations Request').item.json.metadata;
const operationType = $('Process Operations Request').item.json.operation_type;

return {
  json: {
    success: true,
    operation_type: operationType,
    operational_guidance: claudeResponse.response || claudeResponse,
    metadata: metadata,
    timestamp: new Date().toISOString(),
    action_required: operationType === 'problem_solver' ? true : false
  }
};
